CREATE DATABASE IF NOT EXISTS rms CHARACTER SET utf8mb4; USE rms;
CREATE TABLE users(user_id INT AUTO_INCREMENT PRIMARY KEY,full_name VARCHAR(100),national_id VARCHAR(20) UNIQUE,phone VARCHAR(15) UNIQUE,email VARCHAR(100) UNIQUE,password_hash VARCHAR(255),role ENUM('landlord','caretaker','tenant'),landlord_id INT NULL,failed_attempts INT DEFAULT 0,locked_until DATETIME NULL,active TINYINT DEFAULT 1);
CREATE TABLE properties(property_id INT AUTO_INCREMENT PRIMARY KEY,landlord_id INT,property_name VARCHAR(100),location VARCHAR(150),FOREIGN KEY(landlord_id) REFERENCES users(user_id));
CREATE TABLE units(unit_id INT AUTO_INCREMENT PRIMARY KEY,property_id INT,unit_number VARCHAR(20),unit_type ENUM('bedsitter','single room','one-bedroom','two-bedroom+'),rent_amount DECIMAL(10,2),status ENUM('vacant','occupied') DEFAULT 'vacant',FOREIGN KEY(property_id) REFERENCES properties(property_id));
CREATE TABLE tenants(tenant_id INT AUTO_INCREMENT PRIMARY KEY,user_id INT UNIQUE,employment_status VARCHAR(50),emergency_contact VARCHAR(100),move_in_date DATE,FOREIGN KEY(user_id) REFERENCES users(user_id));
CREATE TABLE leases(lease_id INT AUTO_INCREMENT PRIMARY KEY,tenant_id INT,unit_id INT,rent_amount DECIMAL(10,2),deposit_amount DECIMAL(10,2),start_date DATE,end_date DATE,notice_period_days INT,status ENUM('active','expired','terminated') DEFAULT 'active',FOREIGN KEY(tenant_id) REFERENCES tenants(tenant_id),FOREIGN KEY(unit_id) REFERENCES units(unit_id));
CREATE TABLE rent_charges(charge_id INT AUTO_INCREMENT PRIMARY KEY,lease_id INT,period DATE,amount DECIMAL(10,2),due_date DATE,UNIQUE(lease_id,period),FOREIGN KEY(lease_id) REFERENCES leases(lease_id));
CREATE TABLE payments(payment_id INT AUTO_INCREMENT PRIMARY KEY,lease_id INT,tenant_id INT,amount DECIMAL(10,2),payment_date DATETIME,method ENUM('mpesa','cash'),mpesa_code VARCHAR(20) NULL UNIQUE,receipt_number VARCHAR(20),status ENUM('successful','failed','pending'),recorded_by INT NULL,FOREIGN KEY(lease_id) REFERENCES leases(lease_id));
CREATE TABLE maintenance_requests(request_id INT AUTO_INCREMENT PRIMARY KEY,unit_id INT,tenant_id INT,assigned_to INT NULL,description TEXT,date_submitted DATETIME,status ENUM('pending','in progress','resolved') DEFAULT 'pending',date_resolved DATETIME NULL);
CREATE TABLE vacancy_applications(application_id INT AUTO_INCREMENT PRIMARY KEY,unit_id INT,applicant_name VARCHAR(100),applicant_phone VARCHAR(15),message TEXT,date_applied DATETIME,status ENUM('new','approved','rejected') DEFAULT 'new');
CREATE TABLE notifications(notification_id INT AUTO_INCREMENT PRIMARY KEY,user_id INT,message TEXT,type VARCHAR(30),date_sent DATETIME,is_read TINYINT DEFAULT 0);
